use std::rc::Rc;

fn main() {
    let data = Rc::new(42);
    let handle1 = Rc::clone(&data);
    let handle2 = Rc::clone(&data);

    assert_eq!(Rc::strong_count(&handle1), 2);

    let _ = Rc::try_unwrap(handle1).is_err();

    drop(handle2);

    assert_eq!(Rc::strong_count(&data), 1);

    println!("success");
}
